// The original logo at assets/images/og/logo.png is the source of truth.
// These 11 binaries are regenerated by tools/generate-logo-assets.mjs;
// changes in Sharp/libvips can change their bytes without altering catalog data.
// All other tracked file changes remain fail-closed.
import { execFileSync } from 'node:child_process';
import { appendFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export const DERIVED_LOGO_ASSETS = new Set([
  'assets/images/web/logo.webp',
  'assets/images/web/logo.avif',
  ...[40, 80, 120].flatMap((size) => [
    `assets/images/web/logo-${size}.webp`,
    `assets/images/web/logo-${size}.avif`,
  ]),
  'assets/images/web/icon-192.png',
  'assets/images/web/icon-512.png',
  'assets/images/web/favicon.ico',
]);

export function classifyBuildChanges(paths) {
  const ignored = [];
  const unexpected = [];
  for (const path of paths) {
    if (DERIVED_LOGO_ASSETS.has(path)) ignored.push(path);
    else unexpected.push(path);
  }
  return { ignored, unexpected };
}

export function readTrackedChanges(cwd, git = execFileSync) {
  // Relative to HEAD includes staged + unstaged changes. NUL safely handles
  // spaces and non-ASCII characters in tracked filenames.
  const buffer = git('git', ['diff', '--name-only', '-z', 'HEAD', '--'], {
    cwd,
    encoding: 'buffer',
    maxBuffer: 16 * 1024 * 1024,
  });
  return buffer.toString('utf8').split('\0').filter(Boolean);
}

export function checkBuildTree({ cwd = process.cwd(), git = execFileSync } = {}) {
  return classifyBuildChanges(readTrackedChanges(cwd, git));
}

function main() {
  const { ignored, unexpected } = checkBuildTree();
  for (const name of ignored) console.log(`Derived logo regenerated: ${name}`);
  for (const name of unexpected) console.error(`Unexpected tracked build change: ${name}`);
  if (process.env.GITHUB_OUTPUT) {
    appendFileSync(process.env.GITHUB_OUTPUT, `dirty_tree=${unexpected.length ? 'true' : 'false'}\n`);
  }
  // Git failures throw and fail this step instead of being treated as clean.
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main();
}
